{"command":"cd /tmp/t/m2 && cat > exp10.py <<'EOF'
from gen import *
import sys
W,H=40,20
def mx(P): return (W/4-P)/(H/2)
def my(r): return (H/2-r)/(H/2)
def render(tri):
    tris=[[(mx(P),my(r),0) for (P,r) in tri]]
    write_obj("/tmp/t/m2/t.obj", tris, anchor=1.0)
    out=run("/tmp/t/m2/t.obj",W,H)
    d=out.replace('\n','|')
    pts=[(i//W, (i%W)//2) for i,c in enumerate(d) if c=='@']
    byrow={}
    for r,P in pts: byrow.setdefault(r,set()).add(P)
    return {r:sorted(v) for r,v in sorted(byrow.items())}
def expected(tri):
    # exact spans
    import math
    (ax,ay),(bx,by),(cx,cy)=tri
    res={}
    ymin=min(ay,by,cy); ymax=max(ay,by,cy)
    for r in range(max(1,math.ceil(ymin)), min(math.ceil(ymax), H-1)):
        xs=[]
        for (x0,y0),(x1,y1) in [((ax,ay),(bx,by)),((bx,by),(cx,cy)),((cx,cy),(ax,ay))]:
            if (y0<=r<=y1) or (y1<=r<=y0):
                if y0==y1: xs+= [x0,x1]
                else: xs.append(x0+(x1-x0)*(r-y0)/(y1-y0))
        if xs: res[r]=(min(xs),max(xs))
    return res
if __name__=="__main__":
    args=sys.argv[1:]
    tri=[tuple(map(float,a.split(','))) for a in args]
    got=render(tri)
    exp=expected(tri)
    for r in sorted(set(got)|set(exp)):
        print("r=%2d span=%s got=%s"%(r, tuple(round(v,3) for v in exp.get(r,())), got.get(r)))
EOF
