import struct
def r32(x): return struct.unpack('f', struct.pack('f', x))[0]
class F32:
    __slots__=('v',)
    def __init__(self,v): self.v=r32(float(v))
    def __add__(self,o): return F32(self.v+ (o.v if isinstance(o,F32) else r32(o)))
    def __sub__(self,o): return F32(self.v- (o.v if isinstance(o,F32) else r32(o)))
    def __mul__(self,o): return F32(self.v* (o.v if isinstance(o,F32) else r32(o)))
    def __truediv__(self,o): return F32(self.v/ (o.v if isinstance(o,F32) else r32(o)))
    def __neg__(self): return F32(-self.v)
    def __radd__(self,o): return F32(r32(o)+self.v)
    def __rsub__(self,o): return F32(r32(o)-self.v)
    def __rmul__(self,o): return F32(r32(o)*self.v)
    def __rtruediv__(self,o): return F32(r32(o)/self.v)
    def __eq__(self,o): return self.v==(o.v if isinstance(o,F32) else o)
    def __ne__(self,o): return not self.__eq__(o)
    def __lt__(self,o): return self.v<(o.v if isinstance(o,F32) else o)
    def __le__(self,o): return self.v<=(o.v if isinstance(o,F32) else o)
    def __gt__(self,o): return self.v>(o.v if isinstance(o,F32) else o)
    def __ge__(self,o): return self.v>=(o.v if isinstance(o,F32) else o)
    def __float__(self): return self.v
    def __abs__(self): return F32(abs(self.v))
    def __repr__(self): return "F32(%r)"%self.v
    def __hash__(self): return hash(self.v)
class F64(float):
    pass
def mk(dt):
    if dt=='f32': return F32
    return float
