mod data;
use std::collections::HashSet;

const W: f64 = 40.0;
const H: f64 = 20.0;

macro_rules! impl_sim {
    ($name:ident, $t:ty) => {
        mod $name {
            use std::collections::HashSet;
            type T = $t;
            pub fn proj(pv: usize, x: T, y: T) -> (T, T) {
                let w = super::W as T; let h = super::H as T;
                let s = (w / 4.0).min(h / 2.0);
                let cx = w / 4.0; let cy = h / 2.0;
                match pv {
                    0 => (cx - x * s, cy - y * s),
                    1 => (s * (1.0 - x) + (cx - s), s * (1.0 - y) + (cy - s)),
                    2 => ((1.0 - x) * s + (cx - s), (1.0 - y) * s + (cy - s)),
                    3 => ((-x + 1.0) * s + (cx - s), (-y + 1.0) * s + (cy - s)),
                    4 => { let xs = x * s; let ys = y * s; (cx - xs, cy - ys) },
                    5 => (cx - x * (h/2.0), cy - y * (h/2.0)),
                    6 => ((w/2.0 - x * h) / 2.0 , cy - y*s),
                    7 => ((w/2.0 - x * h) / 2.0 , (h - y*h)/2.0),
                    _ => unreachable!(),
                }
            }
            pub fn bary(bv: usize, a: (T,T), b: (T,T), c: (T,T), p: (T,T)) -> Option<[T; 4]> {
                let edge = |a: (T,T), b: (T,T), p: (T,T)| (b.0 - a.0) * (p.1 - a.1) - (b.1 - a.1) * (p.0 - a.0);
                match bv {
                    0 => { let area = edge(a,b,c); if area == 0.0 { return None; }
                           Some([edge(b,c,p)/area, edge(c,a,p)/area, edge(a,b,p)/area, 1.0]) }
                    1 | 2 => {
                        let s0 = (c.0 - a.0, b.0 - a.0, a.0 - p.0);
                        let s1 = (c.1 - a.1, b.1 - a.1, a.1 - p.1);
                        let ux = s0.1 * s1.2 - s0.2 * s1.1;
                        let uy = s0.2 * s1.0 - s0.0 * s1.2;
                        let uz = s0.0 * s1.1 - s0.1 * s1.0;
                        if uz == 0.0 { return None; }
                        if bv == 1 { Some([1.0 - (ux + uy) / uz, uy / uz, ux / uz, 1.0]) }
                        else { Some([1.0 - ux / uz - uy / uz, uy / uz, ux / uz, 1.0]) }
                    }
                    3 => {
                        let v0 = (b.0 - a.0, b.1 - a.1); let v1 = (c.0 - a.0, c.1 - a.1); let v2 = (p.0 - a.0, p.1 - a.1);
                        let d00 = v0.0*v0.0 + v0.1*v0.1; let d01 = v0.0*v1.0 + v0.1*v1.1; let d11 = v1.0*v1.0 + v1.1*v1.1;
                        let d20 = v2.0*v0.0 + v2.1*v0.1; let d21 = v2.0*v1.0 + v2.1*v1.1;
                        let denom = d00 * d11 - d01 * d01; if denom == 0.0 { return None; }
                        let v = (d11 * d20 - d01 * d21) / denom; let w = (d00 * d21 - d01 * d20) / denom;
                        Some([1.0 - v - w, v, w, 1.0])
                    }
                    4 => {
                        let ta = |a: (T,T), b: (T,T), c: (T,T)| ((b.0 - a.0) * (c.1 - a.1) - (c.0 - a.0) * (b.1 - a.1)).abs() / 2.0;
                        let at = ta(a,b,c); if at == 0.0 { return None; }
                        Some([ta(p,b,c)/at, ta(a,p,c)/at, ta(a,b,p)/at, 1.0])
                    }
                    5 => { // raw areas (unnormalized), sum compare with total
                        let ta = |a: (T,T), b: (T,T), c: (T,T)| ((b.0 - a.0) * (c.1 - a.1) - (c.0 - a.0) * (b.1 - a.1)).abs() / 2.0;
                        let at = ta(a,b,c); if at == 0.0 { return None; }
                        Some([ta(p,b,c), ta(a,p,c), ta(a,b,p), at])
                    }
                    6 => { // raw areas without /2
                        let ta = |a: (T,T), b: (T,T), c: (T,T)| ((b.0 - a.0) * (c.1 - a.1) - (c.0 - a.0) * (b.1 - a.1)).abs();
                        let at = ta(a,b,c); if at == 0.0 { return None; }
                        Some([ta(p,b,c), ta(a,p,c), ta(a,b,p), at])
                    }
                    7 => { // standard formula from wikipedia with explicit det
                        let det = (b.1 - c.1) * (a.0 - c.0) + (c.0 - b.0) * (a.1 - c.1);
                        if det == 0.0 { return None; }
                        let l1 = ((b.1 - c.1) * (p.0 - c.0) + (c.0 - b.0) * (p.1 - c.1)) / det;
                        let l2 = ((c.1 - a.1) * (p.0 - c.0) + (a.0 - c.0) * (p.1 - c.1)) / det;
                        Some([l1, l2, 1.0 - l1 - l2, 1.0])
                    }
                    8 => { // same as 7 but l3 computed directly
                        let det = (b.1 - c.1) * (a.0 - c.0) + (c.0 - b.0) * (a.1 - c.1);
                        if det == 0.0 { return None; }
                        let l1 = ((b.1 - c.1) * (p.0 - c.0) + (c.0 - b.0) * (p.1 - c.1)) / det;
                        let l2 = ((c.1 - a.1) * (p.0 - c.0) + (a.0 - c.0) * (p.1 - c.1)) / det;
                        let l3 = ((a.1 - b.1) * (p.0 - b.0) + (b.0 - a.0) * (p.1 - b.1)) / det;
                        Some([l1, l2, l3, 1.0])
                    }
                    _ => unreachable!(),
                }
            }
            pub fn test(tv: usize, bc: [T;4]) -> bool {
                let [u,v,w,t] = bc;
                match tv {
                    0 => u + v + w == t,
                    1 => u + v + w <= t,
                    2 => u + v + w >= t,
                    3 => u >= 0.0 && v >= 0.0 && w >= 0.0 && u + v + w <= t,
                    4 => u >= 0.0 && v >= 0.0 && u + v <= t,
                    5 => v >= 0.0 && w >= 0.0 && v + w <= t,
                    6 => u >= 0.0 && w >= 0.0 && u + w <= t,
                    7 => u >= 0.0 && v >= 0.0 && w >= 0.0,
                    8 => u > 0.0 && v > 0.0 && w > 0.0,
                    9 => (u + v + w - t).abs() < 1e-6,
                    10 => (u + v + w - t).abs() < 1e-5,
                    11 => (u + v + w - t).abs() < 1e-4,
                    12 => (u + v + w - t).abs() < 1e-3,
                    13 => (u + v + w - t).abs() < 1e-7,
                    14 => (u + v + w) - t <= 1e-6,
                    15 => (u + v) + w == t,
                    16 => u + (v + w) == t,
                    17 => w + v + u == t,
                    _ => unreachable!(),
                }
            }
            pub fn simulate(tri: &[(f64,f64,f64);3], parse32: bool, pv: usize, bv: usize, tv: usize) -> Option<HashSet<(i32,i32)>> {
                let mut pts = [(0.0 as T, 0.0 as T); 3];
                for i in 0..3 {
                    let (x, y) = if parse32 { (tri[i].0 as f32 as T, tri[i].1 as f32 as T) } else { (tri[i].0 as T, tri[i].1 as T) };
                    pts[i] = proj(pv, x, y);
                }
                let ymin = pts.iter().map(|p| p.1).fold(T::INFINITY, |a, b| a.min(b));
                let ymax = pts.iter().map(|p| p.1).fold(T::NEG_INFINITY, |a, b| a.max(b));
                let xmin = pts.iter().map(|p| p.0).fold(T::INFINITY, |a, b| a.min(b));
                let xmax = pts.iter().map(|p| p.0).fold(T::NEG_INFINITY, |a, b| a.max(b));
                let mut got = HashSet::new();
                let r0 = (ymin.ceil() as i32).max(1); let r1 = (ymax.ceil() as i32).min(super::H as i32 - 1);
                let p0 = (xmin.ceil() as i32).max(1); let p1 = xmax.floor() as i32;
                for r in r0..r1 { for p in p0..=p1 {
                    let bc = bary(bv, pts[0], pts[1], pts[2], (p as T, r as T))?;
                    if test(tv, bc) { got.insert((r, p)); }
                }}
                Some(got)
            }
        }
    };
}
impl_sim!(s32, f32);
impl_sim!(s64, f64);

fn main() {
    let mut results = vec![];
    for prec in 0..2 { for parse32 in [true, false] { for pv in 0..8 { for bv in 0..9 { for tv in 0..18 {
        let mut score = 0; let mut total = 0; let mut ok = true;
        let mut pixdiff = 0usize;
        for (_name, tri, got) in data::CASES {
            let sim = if prec == 0 { s32::simulate(tri, parse32, pv, bv, tv) } else { s64::simulate(tri, parse32, pv, bv, tv) };
            match sim { None => { ok = false; break; } Some(set) => {
                let obs: HashSet<(i32,i32)> = got.iter().cloned().collect();
                if set == obs { score += 1; }
                pixdiff += set.symmetric_difference(&obs).count();
                total += 1;
            }}
        }
        if ok { results.push((score, total, pixdiff, prec, parse32, pv, bv, tv)); }
    }}}}}
    results.sort_by(|a, b| b.0.cmp(&a.0).then(a.2.cmp(&b.2)));
    for r in results.iter().take(25) { println!("{:?}", r); }
}
