            let s1 = (c.1 - a.1, b.1 - a.1, a.1 - p.1);
            let ux = s0.1 * s1.2 - s0.2 * s1.1;
            let uy = s0.2 * s1.0 - s0.0 * s1.2;
            let uz = s0.0 * s1.1 - s0.1 * s1.0;
