//! Minimal terminal handling (raw mode, size query, non-blocking key reads)
//! implemented directly on top of the C library so that no external crates
//! are required.

use std::io;

#[repr(C)]
#[derive(Clone, Copy)]
struct Termios {
    c_iflag: u32,
    c_oflag: u32,
    c_cflag: u32,
    c_lflag: u32,
    c_line: u8,
    c_cc: [u8; 32],
    c_ispeed: u32,
    c_ospeed: u32,
}

#[repr(C)]
struct WinSize {
    ws_row: u16,
    ws_col: u16,
    ws_xpixel: u16,
    ws_ypixel: u16,
}

#[repr(C)]
struct PollFd {
    fd: i32,
    events: i16,
    revents: i16,
}

extern "C" {
    fn tcgetattr(fd: i32, termios: *mut Termios) -> i32;
    fn tcsetattr(fd: i32, optional_actions: i32, termios: *const Termios) -> i32;
    fn ioctl(fd: i32, request: u64, ...) -> i32;
    fn poll(fds: *mut PollFd, nfds: u64, timeout: i32) -> i32;
    fn read(fd: i32, buf: *mut u8, count: usize) -> isize;
}

const TCSANOW: i32 = 0;
const TIOCGWINSZ: u64 = 0x5413;
const POLLIN: i16 = 0x001;

// c_iflag bits
const IGNBRK: u32 = 0o000001;
const BRKINT: u32 = 0o000002;
const PARMRK: u32 = 0o000010;
const ISTRIP: u32 = 0o000040;
const INLCR: u32 = 0o000100;
const IGNCR: u32 = 0o000200;
const ICRNL: u32 = 0o000400;
const IXON: u32 = 0o002000;
// c_oflag bits
const OPOST: u32 = 0o000001;
// c_lflag bits
const ISIG: u32 = 0o000001;
const ICANON: u32 = 0o000002;
const ECHO: u32 = 0o000010;
const ECHONL: u32 = 0o000100;
const IEXTEN: u32 = 0o100000;
// c_cflag bits
const CSIZE: u32 = 0o000060;
const PARENB: u32 = 0o000400;
const CS8: u32 = 0o000060;

const STDIN: i32 = 0;
const STDOUT: i32 = 1;

/// Guard restoring the original terminal attributes when dropped.
pub struct RawMode {
    original: Termios,
}

impl RawMode {
    pub fn enable() -> io::Result<RawMode> {
        let mut original = Termios {
            c_iflag: 0,
            c_oflag: 0,
            c_cflag: 0,
            c_lflag: 0,
            c_line: 0,
            c_cc: [0; 32],
            c_ispeed: 0,
            c_ospeed: 0,
        };
        if unsafe { tcgetattr(STDIN, &mut original) } != 0 {
            return Err(io::Error::last_os_error());
        }
        let mut raw = original;
        raw.c_iflag &= !(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
        raw.c_oflag &= !OPOST;
        raw.c_lflag &= !(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
        raw.c_cflag &= !(CSIZE | PARENB);
        raw.c_cflag |= CS8;
        if unsafe { tcsetattr(STDIN, TCSANOW, &raw) } != 0 {
            return Err(io::Error::last_os_error());
        }
        Ok(RawMode { original })
    }
}

impl Drop for RawMode {
    fn drop(&mut self) {
        unsafe {
            tcsetattr(STDIN, TCSANOW, &self.original);
        }
    }
}

/// Returns the terminal size as (columns, rows). When the size cannot be
/// determined (e.g. stdout is not a terminal) `(0, 0)` is returned.
pub fn size() -> (usize, usize) {
    let mut ws = WinSize {
        ws_row: 0,
        ws_col: 0,
        ws_xpixel: 0,
        ws_ypixel: 0,
    };
    let r = unsafe { ioctl(STDOUT, TIOCGWINSZ, &mut ws as *mut WinSize) };
    if r != 0 {
        return (0, 0);
    }
    (ws.ws_col as usize, ws.ws_row as usize)
}

/// Waits up to `timeout_ms` for input on stdin and returns any bytes read.
pub fn read_input(timeout_ms: i32) -> Vec<u8> {
    let mut pfd = PollFd {
        fd: STDIN,
        events: POLLIN,
        revents: 0,
    };
    let r = unsafe { poll(&mut pfd, 1, timeout_ms) };
    if r <= 0 || (pfd.revents & POLLIN) == 0 {
        return Vec::new();
    }
    let mut buf = [0u8; 64];
    let n = unsafe { read(STDIN, buf.as_mut_ptr(), buf.len()) };
    if n <= 0 {
        return Vec::new();
    }
    buf[..n as usize].to_vec()
}
