//! Geometry primitives: vectors, triangles, meshes and rotations.

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Vec3 {
    pub x: f32,
    pub y: f32,
    pub z: f32,
}

impl Vec3 {
    pub fn new(x: f32, y: f32, z: f32) -> Vec3 {
        Vec3 { x, y, z }
    }

    pub fn sub(self, o: Vec3) -> Vec3 {
        Vec3::new(self.x - o.x, self.y - o.y, self.z - o.z)
    }

    pub fn cross(self, o: Vec3) -> Vec3 {
        Vec3::new(
            self.y * o.z - self.z * o.y,
            self.z * o.x - self.x * o.z,
            self.x * o.y - self.y * o.x,
        )
    }

    pub fn length(self) -> f32 {
        (self.x * self.x + self.y * self.y + self.z * self.z).sqrt()
    }

    pub fn normalized(self) -> Vec3 {
        let l = self.length();
        Vec3::new(self.x / l, self.y / l, self.z / l)
    }

    pub fn scale(self, s: f32) -> Vec3 {
        Vec3::new(self.x * s, self.y * s, self.z * s)
    }

    /// Rotation about the X axis.
    pub fn rotate_x(self, a: f32) -> Vec3 {
        let (s, c) = a.sin_cos();
        Vec3::new(self.x, self.y * c - self.z * s, self.y * s + self.z * c)
    }

    /// Rotation about the Y axis.
    pub fn rotate_y(self, a: f32) -> Vec3 {
        let (s, c) = a.sin_cos();
        Vec3::new(self.x * c + self.z * s, self.y, -self.x * s + self.z * c)
    }

    /// Rotation about the Z axis.
    pub fn rotate_z(self, a: f32) -> Vec3 {
        let (s, c) = a.sin_cos();
        Vec3::new(self.x * c + self.y * s, -self.x * s + self.y * c, self.z)
    }
}

/// Simple RGB colour.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Color {
    pub r: u8,
    pub g: u8,
    pub b: u8,
}

impl Color {
    pub const fn new(r: u8, g: u8, b: u8) -> Color {
        Color { r, g, b }
    }

    /// Colour used for faces of models that carry no material information.
    pub const WHITE: Color = Color::new(1, 1, 1);
    /// Colour used for STL models.
    pub const YELLOW: Color = Color::new(255, 255, 0);
}

/// A material as read from a `.mtl` library.
#[derive(Clone, Debug, Default)]
pub struct Material {
    pub name: String,
    pub diffuse: [f32; 3],
}

impl Material {
    pub fn color(&self) -> Color {
        Color::new(
            (self.diffuse[0] * 255.0) as u8,
            (self.diffuse[1] * 255.0) as u8,
            (self.diffuse[2] * 255.0) as u8,
        )
    }
}

/// A triangle with a flat colour.
#[derive(Clone, Copy, Debug)]
pub struct Triangle {
    pub v: [Vec3; 3],
    pub color: Color,
}

/// A loaded model: a list of faces plus (optional) material information.
#[derive(Clone, Debug, Default)]
pub struct Mesh {
    pub positions: Vec<Vec3>,
    /// Faces as triples of indices into `positions` together with the
    /// material index that was active when the face was declared.
    pub faces: Vec<([usize; 3], Option<usize>)>,
    pub materials: Vec<Material>,
}

impl Mesh {
    /// Converts the mesh into flat coloured triangles.
    pub fn triangles(&self) -> Vec<Triangle> {
        let mut out = Vec::with_capacity(self.faces.len());
        for (idx, material) in &self.faces {
            let color = if self.materials.is_empty() { Color::WHITE } else { self.materials[material.unwrap()].color() };
            out.push(Triangle { v: [self.positions[idx[0]], self.positions[idx[1]], self.positions[idx[2]]], color });
        }
        out
    }
}

/// Static rotation applied to the scene (in radians).
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Rotation {
    pub x: f32,
    pub y: f32,
    pub z: f32,
}

impl Rotation {
    pub fn apply(&self, v: Vec3) -> Vec3 {
        v.rotate_x(self.x).rotate_y(self.y).rotate_z(self.z)
    }
}

/// Scales all triangles so that the largest absolute coordinate becomes 1.
pub fn normalize(tris: &mut [Triangle]) {
    let mut max = 0.0f32;
    for t in tris.iter() {
        for v in &t.v {
            max = max.max(v.x.abs()).max(v.y.abs()).max(v.z.abs());
        }
    }
    if max > 0.0 {
        for t in tris.iter_mut() {
            for v in &mut t.v {
                *v = v.scale(1.0 / max);
            }
        }
    }
}
