//! Model loading: Wavefront OBJ (with MTL material libraries) and STL
//! (ASCII and binary) files.

use crate::geometry::{Material, Mesh, Triangle, Vec3};
use std::fmt;
use std::fs::File;
use std::io::{self, BufRead, BufReader, Read};
use std::path::Path;

/// Errors produced while reading OBJ / MTL files.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LoadError {
    OpenFileFailed,
    ReadError,
    PositionParseError,
    NormalParseError,
    TexcoordParseError,
    FaceParseError,
    MaterialParseError,
    FaceVertexOutOfBounds,
}

impl fmt::Display for LoadError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let msg = match self {
            LoadError::OpenFileFailed => "open file failed",
            LoadError::ReadError => "read error",
            LoadError::PositionParseError => "position parse error",
            LoadError::NormalParseError => "normal parse error",
            LoadError::TexcoordParseError => "texcoord parse error",
            LoadError::FaceParseError => "face parse error",
            LoadError::MaterialParseError => "material parse error",
            LoadError::FaceVertexOutOfBounds => "face vertex index out of bounds",
        };
        write!(f, "{}", msg)
    }
}

fn parse_floats(words: &mut std::str::SplitWhitespace, n: usize, err: LoadError) -> Result<Vec<f32>, LoadError> {
    let mut out = Vec::with_capacity(n);
    for _ in 0..n {
        let w = words.next().ok_or(err)?;
        out.push(w.parse::<f32>().map_err(|_| err)?);
    }
    Ok(out)
}

/// Loads a material library.
fn load_mtl(path: &Path) -> Result<Vec<Material>, LoadError> {
    let file = File::open(path).map_err(|_| LoadError::OpenFileFailed)?;
    let reader = BufReader::new(file);
    let mut materials: Vec<Material> = Vec::new();
    for line in reader.lines() {
        let line = line.map_err(|_| LoadError::ReadError)?;
        let mut words = line.split_whitespace();
        match words.next() {
            Some("newmtl") => {
                let name = words.collect::<Vec<_>>().join(" ");
                materials.push(Material { name, diffuse: [0.0, 0.0, 0.0] });
            }
            Some("Kd") => {
                let v = parse_floats(&mut words, 3, LoadError::MaterialParseError)?;
                if let Some(m) = materials.last_mut() {
                    m.diffuse = [v[0], v[1], v[2]];
                }
            }
            Some("Ka") | Some("Ks") | Some("Ke") => {
                parse_floats(&mut words, 3, LoadError::MaterialParseError)?;
            }
            Some("Ns") | Some("Ni") | Some("d") => {
                parse_floats(&mut words, 1, LoadError::MaterialParseError)?;
            }
            _ => {}
        }
    }
    Ok(materials)
}

/// Resolves a single face vertex reference ("i", "i/t", "i//n", "i/t/n").
fn face_index(word: &str, count: usize) -> Result<usize, LoadError> {
    let idx_str = word.split('/').next().ok_or(LoadError::FaceParseError)?;
    let idx: isize = idx_str.parse().map_err(|_| LoadError::FaceParseError)?;
    let resolved = if idx > 0 { idx as usize - 1 } else if idx < 0 { (count as isize + idx) as usize } else { return Err(LoadError::FaceVertexOutOfBounds) };
    if idx < 0 && (count as isize + idx) < 0 { return Err(LoadError::FaceVertexOutOfBounds); }
    if resolved >= count { return Err(LoadError::FaceVertexOutOfBounds); }
    Ok(resolved)
}

/// Loads an OBJ file. Returns the geometry together with the result of
/// loading the referenced material library (if any).
fn load_obj(path: &Path) -> Result<(Mesh, Result<Vec<Material>, LoadError>), LoadError> {
    let file = File::open(path).map_err(|_| LoadError::OpenFileFailed)?;
    let reader = BufReader::new(file);
    let mut mesh = Mesh::default();
    let mut materials: Result<Vec<Material>, LoadError> = Ok(Vec::new());
    let mut current_material: Option<usize> = None;
    for line in reader.lines() {
        let line = line.map_err(|_| LoadError::ReadError)?;
        let mut words = line.split_whitespace();
        match words.next() {
            Some("v") => {
                let v = parse_floats(&mut words, 3, LoadError::PositionParseError)?;
                mesh.positions.push(Vec3::new(v[0], v[1], v[2]));
            }
            Some("vn") => {
                parse_floats(&mut words, 3, LoadError::NormalParseError)?;
            }
            Some("vt") => {
                parse_floats(&mut words, 2, LoadError::TexcoordParseError)?;
            }
            Some("f") => {
                let mut idx = Vec::new();
                for w in words {
                    idx.push(face_index(w, mesh.positions.len())?);
                }
                for i in 1..idx.len().saturating_sub(1) {
                    mesh.faces.push(([idx[0], idx[i], idx[i + 1]], current_material));
                }
            }
            Some("usemtl") => {
                let name = words.collect::<Vec<_>>().join(" ");
                current_material = match &materials {
                    Ok(list) => list.iter().position(|m| m.name == name),
                    Err(_) => None,
                };
            }
            Some("mtllib") => {
                let name = words.collect::<Vec<_>>().join(" ");
                let mtl_path = match path.parent() {
                    Some(dir) => dir.join(&name),
                    None => Path::new(&name).to_path_buf(),
                };
                materials = load_mtl(&mtl_path);
            }
            _ => {}
        }
    }
    Ok((mesh, materials))
}

fn io_err<E: std::error::Error + Send + Sync + 'static>(kind: io::ErrorKind, e: E) -> io::Error {
    io::Error::new(kind, e)
}

fn stl_data_err(msg: String) -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, msg)
}

/// Parses an ASCII STL body.
fn read_ascii_stl(data: &[u8]) -> io::Result<Vec<[Vec3; 3]>> {
    let text = String::from_utf8_lossy(data);
    let mut lines = text.lines().map(|l| l.trim()).filter(|l| !l.is_empty());
    let first = lines.next().ok_or_else(|| io::Error::new(io::ErrorKind::UnexpectedEof, "unexpected end of file"))?;
    if !first.starts_with("solid") {
        return Err(stl_data_err("ascii STL does not start with \"solid \"".to_string()));
    }
    let mut tris = Vec::new();
    loop {
        let tokens: Vec<&str> = match lines.next() {
            Some(l) => l.split_whitespace().collect(),
            None => return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "unexpected end of file")),
        };
        if tokens.first() == Some(&"endsolid") {
            break;
        }
        if tokens.len() != 5 || tokens[0] != "facet" || tokens[1] != "normal" || tokens[2..].iter().any(|t| t.parse::<f32>().is_err()) {
            return Err(stl_data_err(format!("facet normal f32 f32 f32, got {:?}", tokens)));
        }
        let tokens: Vec<&str> = lines.next().map(|l| l.split_whitespace().collect()).ok_or_else(|| io::Error::new(io::ErrorKind::UnexpectedEof, "unexpected end of file"))?;
        if tokens != ["outer", "loop"] {
            return Err(stl_data_err(format!("outer loop, got {:?}", tokens)));
        }
        let mut verts = [Vec3::new(0.0, 0.0, 0.0); 3];
        for vert in verts.iter_mut() {
            let tokens: Vec<&str> = lines.next().map(|l| l.split_whitespace().collect()).ok_or_else(|| io::Error::new(io::ErrorKind::UnexpectedEof, "unexpected end of file"))?;
            let parsed: Option<Vec<f32>> = if tokens.len() == 4 && tokens[0] == "vertex" { tokens[1..].iter().map(|t| t.parse::<f32>().ok()).collect() } else { None };
            match parsed {
                Some(v) => *vert = Vec3::new(v[0], v[1], v[2]),
                None => return Err(stl_data_err(format!("vertex f32 f32 f32, got {:?}", tokens))),
            }
        }
        let tokens: Vec<&str> = lines.next().map(|l| l.split_whitespace().collect()).ok_or_else(|| io::Error::new(io::ErrorKind::UnexpectedEof, "unexpected end of file"))?;
        if tokens != ["endloop"] {
            return Err(stl_data_err(format!("endloop, got {:?}", tokens)));
        }
        let tokens: Vec<&str> = lines.next().map(|l| l.split_whitespace().collect()).ok_or_else(|| io::Error::new(io::ErrorKind::UnexpectedEof, "unexpected end of file"))?;
        if tokens != ["endfacet"] {
            return Err(stl_data_err(format!("endfacet, got {:?}", tokens)));
        }
        tris.push(verts);
    }
    Ok(tris)
}

/// Parses a binary STL body.
fn read_binary_stl(data: &[u8]) -> io::Result<Vec<[Vec3; 3]>> {
    let mut cursor = io::Cursor::new(data);
    let mut header = [0u8; 80];
    cursor.read_exact(&mut header)?;
    let mut count_bytes = [0u8; 4];
    cursor.read_exact(&mut count_bytes)?;
    let count = u32::from_le_bytes(count_bytes);
    let mut tris = Vec::new();
    for _ in 0..count {
        let mut buf = [0u8; 50];
        cursor.read_exact(&mut buf)?;
        let f = |i: usize| f32::from_le_bytes([buf[i], buf[i + 1], buf[i + 2], buf[i + 3]]);
        let mut verts = [Vec3::new(0.0, 0.0, 0.0); 3];
        for (k, vert) in verts.iter_mut().enumerate() {
            let base = 12 + k * 12;
            *vert = Vec3::new(f(base), f(base + 4), f(base + 8));
        }
        tris.push(verts);
    }
    Ok(tris)
}

/// Loads an STL file (ASCII or binary).
fn load_stl(path: &Path) -> Result<Vec<[Vec3; 3]>, String> {
    let mut file = File::open(path).map_err(|e| format!("STL load failed. {}", e))?;
    let mut data = Vec::new();
    file.read_to_end(&mut data).map_err(|e| format!("STL load failed. {}", e))?;
    let first_line_is_solid = {
