//! Model loading: Wavefront OBJ (with MTL material libraries) and STL
//! (ASCII and binary) files.
//!
//! A model argument may name several files separated by whitespace; every
//! file is loaded independently and the resulting triangles are concatenated.
//! The file type is chosen from the extension:
//!
//! * `.obj` - Wavefront OBJ.  Only the geometry (`v` / `f` records) and the
//!   material assignments (`mtllib` / `usemtl`) are used.  Texture coordinates
//!   and normals are validated but otherwise ignored: shading always uses the
//!   geometric face normal.  Polygons with more than three vertices are
//!   triangulated as a fan around the first vertex and negative indices are
//!   resolved relative to the vertices declared so far.
//!
//!   A referenced material library is mandatory: when the `.mtl` file cannot
//!   be read, loading aborts.  Faces are coloured with the diffuse (`Kd`)
//!   colour of the material that was active when the face was declared,
//!   scaled to 0..255.  When the model does not reference any material
//!   library at all, every face receives a neutral default colour instead.
//!   Referencing a material that does not exist in the library is an error
//!   that surfaces later, when the colour of the face is resolved.
//!
//! * `.stl` - ASCII or binary STL.  The flavour is detected from the first
//!   line: files starting with "solid " are parsed as ASCII, anything else as
//!   binary (80 byte header, triangle count, 50 byte records).  The per-facet
//!   normals stored in the file are ignored in favour of the geometric
//!   normal.  STL carries no colour information, so a fixed yellow is used.
//!
//! Any other extension is rejected.  Errors are reported through `String`
//! messages that mimic the wording of the underlying parsers.

use crate::geometry::{Color, Material, Mesh, Triangle, Vec3};
use std::fmt;
use std::fs::File;
use std::io::{self, BufRead, BufReader, Read};
use std::path::Path;

/// Errors produced while reading OBJ / MTL files.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum LoadError {
    OpenFileFailed,
    ReadError,
    PositionParseError,
    NormalParseError,
    TexcoordParseError,
    FaceParseError,
    MaterialParseError,
    FaceVertexOutOfBounds,
}

impl fmt::Display for LoadError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let msg = match self {
            LoadError::OpenFileFailed => "open file failed",
            LoadError::ReadError => "read error",
            LoadError::PositionParseError => "position parse error",
            LoadError::NormalParseError => "normal parse error",
            LoadError::TexcoordParseError => "texcoord parse error",
            LoadError::FaceParseError => "face parse error",
            LoadError::MaterialParseError => "material parse error",
            LoadError::FaceVertexOutOfBounds => "face vertex index out of bounds",
        };
        write!(f, "{}", msg)
    }
}

/// Parses `n` whitespace separated floats.
fn parse_floats(words: &mut std::str::SplitWhitespace, n: usize, err: LoadError) -> Result<Vec<f32>, LoadError> {
    let mut out = Vec::with_capacity(n);
    for _ in 0..n {
        let w = words.next().ok_or(err)?;
        out.push(w.parse::<f32>().map_err(|_| err)?);
    }
    Ok(out)
}

/// Resolves a single face vertex reference ("i", "i/t", "i//n", "i/t/n").
fn face_index(word: &str, count: usize) -> Result<usize, LoadError> {
    let idx_str = word.split('/').next().ok_or(LoadError::FaceParseError)?;
    let idx: isize = idx_str.parse().map_err(|_| LoadError::FaceParseError)?;
    let resolved = if idx > 0 {
        idx - 1
    } else if idx < 0 {
        count as isize + idx
    } else {
        return Err(LoadError::FaceVertexOutOfBounds);
    };
    if resolved < 0 || resolved as usize >= count {
        return Err(LoadError::FaceVertexOutOfBounds);
    }
    Ok(resolved as usize)
}

/// Builds the error message used when a model file cannot be loaded.
fn load_failure(filename: &str, err: String) -> String {
    format!("filename: [{}] couldn't load, {}", filename, err)
}

/// Loads a single model file into coloured triangles.
fn load_model(filename: &str) -> Result<Vec<Triangle>, String> {
    let path = Path::new(filename);
    let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
    match ext {
        "obj" => {
            let loaded = load_obj(path);
            let (mut mesh, materials) = loaded.map_err(|e| format!("tobj couldnt load/parse OBJ. {}", e))?;
            let materials = materials.expect("Expected to have materials.");
            mesh.materials = materials;
            Ok(mesh.triangles())
        }
        "stl" => Ok(load_stl(path)?.into_iter().map(|v| Triangle { v, color: Color::YELLOW }).collect()),
        _ => Err(format!("unknown filename extension. {}", "")),
    }
}

/// Loads every model named in `arg` (whitespace separated).
pub fn load_models(arg: &str) -> Vec<Triangle> {
    let mut all = Vec::new();
    for filename in arg.split_whitespace() {
        let loaded_result = load_model(filename).map_err(|e| load_failure(filename, e));
        let triangles = loaded_result.unwrap();
        all.extend(triangles);
    }
    all
}

/// Loads a material library.
fn load_mtl(path: &Path) -> Result<Vec<Material>, LoadError> {
    let file = File::open(path).map_err(|_| LoadError::OpenFileFailed)?;
    let reader = BufReader::new(file);
    let mut materials: Vec<Material> = Vec::new();
    for line in reader.lines() {
        let line = line.map_err(|_| LoadError::ReadError)?;
        let mut words = line.split_whitespace();
        match words.next() {
            Some("newmtl") => {
                let name = words.collect::<Vec<_>>().join(" ");
                materials.push(Material { name, diffuse: [0.0, 0.0, 0.0] });
            }
            Some("Kd") => {
                let v = parse_floats(&mut words, 3, LoadError::MaterialParseError)?;
                if let Some(m) = materials.last_mut() {
                    m.diffuse = [v[0], v[1], v[2]];
                }
            }
            Some("Ka") | Some("Ks") | Some("Ke") => {
                parse_floats(&mut words, 3, LoadError::MaterialParseError)?;
            }
            Some("Ns") | Some("Ni") | Some("d") => {
                parse_floats(&mut words, 1, LoadError::MaterialParseError)?;
            }
            _ => {}
        }
    }
    Ok(materials)
}

/// Loads an OBJ file. Returns the geometry together with the result of
/// loading the referenced material library (if any).
fn load_obj(path: &Path) -> Result<(Mesh, Result<Vec<Material>, LoadError>), LoadError> {
    let file = File::open(path).map_err(|_| LoadError::OpenFileFailed)?;
    let reader = BufReader::new(file);
    let mut mesh = Mesh::default();
    let mut materials: Result<Vec<Material>, LoadError> = Ok(Vec::new());
    let mut current_material: Option<usize> = None;
    for line in reader.lines() {
        let line = line.map_err(|_| LoadError::ReadError)?;
        let mut words = line.split_whitespace();
        match words.next() {
            Some("v") => {
                let v = parse_floats(&mut words, 3, LoadError::PositionParseError)?;
                mesh.positions.push(Vec3::new(v[0], v[1], v[2]));
