{"command":"cd /workspace && cat > src/cli.rs <<'EOF'
//! Command line parsing.
//!
//! The interface (help texts, usage lines and error messages) follows the
//! conventions of the classic clap 2 style: short/long flags, options taking a
//! value either as the next argument or attached (`-w5`, `-w=5`, `--yaw=1`),
//! clustered short flags (`-bx 1`), a `--` terminator, a `help` subcommand and
//! "did you mean" suggestions based on the Jaro-Winkler similarity.

use std::collections::HashMap;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Kind {
    Flag,
    Opt,
}

#[derive(Clone, Copy, Debug)]
struct ArgDef {
    /// Internal name; also used as the value placeholder for options.
    name: &'static str,
    short: Option<char>,
    long: Option<&'static str>,
    kind: Kind,
    required: bool,
}

impl ArgDef {
    /// Rendering used in usage strings and error messages.
    fn display(&self) -> String {
        let head = match (self.long, self.short) {
            (Some(l), _) => format!("--{}", l),
            (None, Some(s)) => format!("-{}", s),
            (None, None) => String::new(),
        };
        match self.kind {
            Kind::Flag => head,
            Kind::Opt => format!("{} <{}>", head, self.name),
        }
    }
}

const fn flag(name: &'static str, short: Option<char>, long: Option<&'static str>) -> ArgDef {
    ArgDef { name, short, long, kind: Kind::Flag, required: false }
}

const fn opt(name: &'static str, short: Option<char>, long: Option<&'static str>, required: bool) -> ArgDef {
    ArgDef { name, short, long, kind: Kind::Opt, required }
}

/// Definition of one (sub)command.
struct CmdDef {
    name: &'static str,
    args: &'static [ArgDef],
    /// Name of the (required, multiple) positional argument, if any.
    positional: Option<&'static str>,
    subcommands: &'static [&'static str],
    /// Short flag triggering the help output (`-h` is an option in `image`).
    help_short: Option<char>,
}

const TOP_ARGS: &[ArgDef] = &[
    flag("help", Some('h'), Some("help")),
    flag("b", Some('b'), None),
    flag("version", Some('V'), Some("version")),
    opt("x", Some('x'), Some("yaw"), false),
    opt("y", Some('y'), Some("pitch"), false),
    opt("z", Some('z'), Some("roll"), false),
];

const IMAGE_ARGS: &[ArgDef] = &[
    flag("help", None, Some("help")),
    flag("b", Some('b'), None),
    flag("version", Some('V'), Some("version")),
    opt("frame count", Some('j'), Some("webify"), false),
    opt("height", Some('h'), None, false),
    opt("width", Some('w'), None, true),
    opt("x", Some('x'), Some("yaw"), false),
    opt("y", Some('y'), Some("pitch"), false),
    opt("z", Some('z'), Some("roll"), false),
];

const TOP: CmdDef = CmdDef {
    name: "",
    args: TOP_ARGS,
    positional: Some("input filename(s)"),
    subcommands: &["help", "image"],
    help_short: Some('h'),
};

const IMAGE: CmdDef = CmdDef {
    name: "image",
    args: IMAGE_ARGS,
    positional: None,
    subcommands: &[],
    help_short: None,
};

const GOOD_START: &str = "\x1b[32m";
const GOOD_END: &str = "\x1b[0m";

/// Result of a parse that terminates the program (help, version or error).
#[derive(Debug, Clone)]
pub struct Exit {
    pub message: String,
    pub code: i32,
}

impl Exit {
    fn error(message: String) -> Exit {
        Exit { message, code: 1 }
    }

    fn output(message: String) -> Exit {
        Exit { message, code: 0 }
    }
}

/// Values collected for one command.
#[derive(Debug, Default, Clone)]
pub struct Matches {
    occurrences: HashMap<&'static str, u32>,
    values: HashMap<&'static str, Vec<String>>,
    /// Argument names in the order they were first seen.
    order: Vec<&'static str>,
    pub positionals: Vec<String>,
}

impl Matches {
    pub fn is_present(&self, name: &str) -> bool {
        self.occurrences.contains_key(name)
    }

    pub fn value_of(&self, name: &str) -> Option<&str> {
        self.values.get(name).and_then(|v| v.first()).map(|s| s.as_str())
    }

    fn note(&mut self, name: &'static str) {
        if !self.occurrences.contains_key(name) {
            self.order.push(name);
        }
        *self.occurrences.entry(name).or_insert(0) += 1;
    }
}

/// Fully parsed command line.
#[derive(Debug, Clone)]
pub struct ParsedArgs {
    pub bin_name: String,
    pub top: Matches,
    pub image: Option<Matches>,
}

// ---------------------------------------------------------------------------
// Help texts
// ---------------------------------------------------------------------------

pub fn top_help(bin: &str) -> String {
    format!(
        "Sloth 0.1
Mitchell Hynes. <mshynes@mun.ca>
A toy for rendering 3D objects in the command line

USAGE:
    {bin} [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]

FLAGS:
    -h, --help       Prints help information
    -b               Flags the rasterizer to render without color
    -V, --version    Prints version information

OPTIONS:
    -x, --yaw <x>      Sets the object's static X rotation (in radians)
    -y, --pitch <y>    Sets the object's static Y rotation (in radians)
    -z, --roll <z>     Sets the object's static Z rotation (in radians)

ARGS:
    <input filename(s)>...    Sets the input file to render

SUBCOMMANDS:
    help     Prints this message or the help of the given subcommand(s)
    image    Generates a colorless terminal output as lines of text
",
        bin = bin
    )
}

fn image_help(bin: &str, prefix: &str) -> String {
    format!(
        "{bin}-image 
Mitchell Hynes <mitchell.hynes@ecumene.xyz>
Generates a colorless terminal output as lines of text

USAGE:
    {prefix} [FLAGS] [OPTIONS] -w <width>

FLAGS:
        --help       Prints help information
    -b               Flags the rasterizer to render without color
    -V, --version    Prints version information

OPTIONS:
    -j, --webify <frame count>    Generates a portable JS based render of your object for the web
    -h <height>                   Sets the height of the image to generate
    -w <width>                    Sets the width of the image to generate
    -x, --yaw <x>                 Sets the object's static X rotation (in radians)
    -y, --pitch <y>               Sets the object's static Y rotation (in radians)
    -z, --roll <z>                Sets the object's static Z rotation (in radians)
",
        bin = bin,
        prefix = prefix
    )
}

fn help_help(bin: &str) -> String {
    format!(
        "{bin}-help 
Prints this message or the help of the given subcommand(s)

USAGE:
    {bin} help [subcommand]...

ARGS:
    <subcommand>...    The subcommand whose help message to display
",
        bin = bin
    )
}

fn top_version() -> String {
    "Sloth 0.1\n".to_string()
}

fn image_version(bin: &str) -> String {
    format!("{}-image \n", bin)
}

// ---------------------------------------------------------------------------
// Similarity (Jaro-Winkler) used for suggestions
// ---------------------------------------------------------------------------

fn jaro(a: &str, b: &str) -> f64 {
    let a_chars: Vec<char> = a.chars().collect();
    let b_chars: Vec<char> = b.chars().collect();
    let a_len = a_chars.len();
    let b_len = b_chars.len();
    if a_len == 0 && b_len == 0 {
        return 1.0;
    } else if a_len == 0 || b_len == 0 {
        return 0.0;
    } else if a_len == 1 && b_len == 1 {
        return if a_chars[0] == b_chars[0] { 1.0 } else { 0.0 };
    }
    let search_range = (a_len.max(b_len) / 2).saturating_sub(1);
    let mut b_consumed = vec![false; b_len];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for (i, &a_char) in a_chars.iter().enumerate() {
        let min_bound = i.saturating_sub(search_range);
        let max_bound = (b_len - 1).min(i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for (j, &b_char) in b_chars.iter().enumerate() {
            if min_bound <= j && j <= max_bound && a_char == b_char && !b_consumed[j] {
                b_consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0) * ((matches / a_len as f64) + (matches / b_len as f64) + ((matches - transpositions) / matches))
    }
}

fn jaro_winkler(a: &str, b: &str) -> f64 {
    let jaro_distance = jaro(a, b);
    let prefix_length = a.chars().zip(b.chars()).take_while(|(x, y)| x == y).count();
    let d = jaro_distance + (0.1 * prefix_length as f64 * (1.0 - jaro_distance));
    if d <= 1.0 {
        d
    } else {
        1.0
    }
}

fn did_you_mean<'a>(value: &str, candidates: impl IntoIterator<Item = &'a str>) -> Option<&'a str> {
    let mut best: Option<(f64, &'a str)> = None;
    for c in candidates {
        let confidence = jaro_winkler(value, c);
        if confidence > 0.8 && best.map_or(true, |(score, _)| score < confidence) {
            best = Some((confidence, c));
        }
    }
    best.map(|(_, c)| c)
}

// ---------------------------------------------------------------------------
// The parser
// ---------------------------------------------------------------------------

struct Parser<'a> {
    bin: &'a str,
    def: &'static CmdDef,
    /// Usage prefix, e.g. "executable" or "executable image".
    prefix: String,
    matches: Matches,
    /// Option waiting for its value.
    pending: Option<&'static ArgDef>,
    trailing: bool,
}

impl<'a> Parser<'a> {
    fn new(bin: &'a str, def: &'static CmdDef, prefix: String) -> Parser<'a> {
        Parser { bin, def, prefix, matches: Matches::default(), pending: None, trailing: false }
    }

    fn find_long(&self, long: &str) -> Option<&'static ArgDef> {
        self.def.args.iter().find(|a| a.long == Some(long))
    }

    fn find_short(&self, short: char) -> Option<&'static ArgDef> {
        self.def.args.iter().find(|a| a.short == Some(short))
    }

    fn find_name(&self, name: &str) -> Option<&'static ArgDef> {
        self.def.args.iter().find(|a| a.name == name)
    }

    /// The complete usage line shown in help output.
    fn full_usage(&self) -> String {
        if self.def.positional.is_some() {
            format!("{} [FLAGS] [OPTIONS] <input filename(s)>... [SUBCOMMAND]", self.prefix)
        } else {
            format!("{} [FLAGS] [OPTIONS] -w <width>", self.prefix)
        }
    }

    /// Usage line for error messages: lists the arguments used so far plus
    /// all required ones.  Falls back to the full usage when nothing has been
    /// used yet.
    fn error_usage(&self, extra: Option<&str>) -> String {
        let mut used: Vec<&str> = self
            .matches
            .order
            .iter()
            .copied()
            .filter(|n| self.find_name(n).map_or(false, |a| !a.required))
            .collect();
        if let Some(e) = extra {
            used.push(e);
        }
        if used.is_empty() {
            return self.full_usage();
        }
        let mut names: Vec<&str> = used;
        for a in self.def.args.iter().filter(|a| a.required) {
            names.push(a.name);
        }
        names.sort();
        names.dedup();
        let mut usage = self.prefix.clone();
        if let Some(p) = self.def.positional {
            usage.push_str(&format!(" <{}>...", p));
        }
        for n in names {
            if let Some(a) = self.find_name(n) {
                usage.push_str(" ");
                usage.push_str(&a.display());
            }
        }
        usage
    }

    fn help_text(&self) -> String {
        if self.def.positional.is_some() {
            top_help(self.bin)
        } else {
            image_help(self.bin, &self.prefix)
        }
    }

    fn version_text(&self) -> String {
        if self.def.positional.is_some() {
            top_version()
        } else {
            image_version(self.bin)
        }
    }

    fn fail(&self, body: String, usage: String) -> Exit {
        Exit::error(format!("error: {}\n\nUSAGE:\n    {}\n\nFor more information try --help\n", body, usage))
    }

    fn unknown_argument(&self, arg: &str, suggestion: Option<&'static ArgDef>) -> Exit {
        let mut body = format!("Found argument '{}' which wasn't expected, or isn't valid in this context", arg);
        if let Some(s) = suggestion {
            body.push_str(&format!(
                "\n\tDid you mean {}--{}{}{}{}?",
                GOOD_START,
                GOOD_END,
                GOOD_START,
                s.long.unwrap_or(""),
                GOOD_END
            ));
        }
        let usage = self.error_usage(suggestion.map(|s| s.name));
        self.fail(body, usage)
    }

    fn record_flag(&mut self, a: &'static ArgDef) -> Result<(), Exit> {
        match a.name {
            "help" => Err(Exit::output(self.help_text())),
            "version" => Err(Exit::output(self.version_text())),
            _ => {
                self.matches.note(a.name);
                Ok(())
            }
        }
    }

    fn add_value(&mut self, a: &'static ArgDef, value: String) {
        self.matches.values.entry(a.name).or_default().push(value);
    }

    /// Handles `--name` / `--name=value`.
    fn parse_long(&mut self, arg: &str) -> Result<(), Exit> {
        let body = &arg[2..];
        let (name, value) = match body.find('=') {
            Some(i) => (&body[..i], Some(body[i + 1..].to_string())),
            None => (body, None),
        };
        match self.find_long(name) {
            Some(a) if a.kind == Kind::Flag => {
                self.record_flag(a)?;
                Ok(())
            }
            Some(a) => {
                self.matches.note(a.name);
                match value {
                    Some(v) => self.add_value(a, v),
                    None => self.pending = Some(a),
                }
                Ok(())
            }
            None => {
                let longs = self.def.args.iter().filter_map(|a| a.long);
                let suggestion = did_you_mean(name, longs).and_then(|l| self.find_long(l));
                Err(self.unknown_argument(&format!("--{}", name), suggestion))
            }
        }
    }

    /// Handles `-abc`, `-w5`, `-w=5`, ...
    fn parse_short_cluster(&mut self, arg: &str) -> Result<(), Exit> {
        let cluster: Vec<char> = arg[1..].chars().collect();
        let mut i = 0;
        while i < cluster.len() {
            let c = cluster[i];
            if Some(c) == self.def.help_short {
                return Err(Exit::output(self.help_text()));
            }
            match self.find_short(c) {
                Some(a) if a.kind == Kind::Flag => {
                    self.record_flag(a)?;
                    i += 1;
                }
                Some(a) => {
                    self.matches.note(a.name);
                    let rest: String = cluster[i + 1..].iter().collect();
                    if rest.is_empty() {
                        self.pending = Some(a);
                    } else {
                        let v = rest.strip_prefix('=').unwrap_or(&rest).to_string();
                        self.add_value(a, v);
                    }
                    return Ok(());
                }
                None => return Err(self.unknown_argument(&format!("-{}", c), None)),
            }
        }
        Ok(())
    }

    /// Final checks performed once all arguments have been consumed.
    fn validate(&self) -> Result<(), Exit> {
        // Required arguments.
        let mut missing: Vec<String> = Vec::new();
        if let Some(p) = self.def.positional {
            if self.matches.positionals.is_empty() {
                missing.push(format!("<{}>...", p));
            }
        }
        for a in self.def.args.iter().filter(|a| a.required) {
            if !self.matches.is_present(a.name) {
                missing.push(a.display());
            }
        }
        if !missing.is_empty() {
            let list = missing.iter().map(|m| format!("    {}", m)).collect::<Vec<_>>().join("\n");
            let body = format!("The following required arguments were not provided:\n{}", list);
            let usage = self.error_usage(None);
            return Err(Exit::error(format!("error: {}\n\nUSAGE:\n    {}\n\nFor more information try --help\n", body, usage)));
        }
        // Options without a value and arguments given more than once.
        for a in self.def.args {
            let occurrences = match self.matches.occurrences.get(a.name) {
                Some(&n) => n,
                None => continue,
            };
            if a.kind == Kind::Opt && self.matches.values.get(a.name).map_or(true, |v| v.is_empty()) {
                let body = format!("The argument '{}' requires a value but none was supplied", a.display());
                return Err(self.fail(body, self.error_usage(None)));
            }
            if occurrences > 1 {
                let body = format!(
                    "The argument '{}' was provided more than once, but cannot be used multiple times",
                    a.display()
                );
                return Err(self.fail(body, self.error_usage(None)));
            }
        }
        Ok(())
    }
}

/// Error for an unknown `help` target.
fn unrecognized_subcommand(bin: &str, name: &str) -> Exit {
    Exit::error(format!(
        "error: The subcommand '{}' wasn't recognized\n\nUSAGE:\n\t{} help <subcommands>...\n\nFor more information try --help\n",
        name, bin
    ))
}

/// Handles `help [subcommand]...`.
fn run_help(bin: &str, rest: &[String], image_prefix: &str) -> Exit {
    match rest.first().map(|s| s.as_str()) {
        None => Exit::output(top_help(bin)),
        Some("image") => {
            if rest.len() > 1 {
                return unrecognized_subcommand(bin, &rest[1]);
            }
            Exit::output(image_help(bin, image_prefix))
        }
        Some("help") => {
            if rest.len() > 1 {
                return unrecognized_subcommand(bin, &rest[1]);
            }
            Exit::output(help_help(bin))
        }
        Some(other) => unrecognized_subcommand(bin, other),
    }
}

/// Parses the complete command line.  `args` excludes the program name.
pub fn parse(bin: &str, args: &[String]) -> Result<ParsedArgs, Exit> {
    let mut top = Parser::new(bin, &TOP, bin.to_string());
    let mut image: Option<Matches> = None;
    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        i += 1;
        let starts_new_arg = !top.trailing && arg.starts_with('-') && arg.len() > 1;
        if !top.trailing && arg == "--" && top.pending.is_none() {
            top.trailing = true;
            continue;
        }
        if starts_new_arg {
            // A pending option never swallows something that looks like a flag.
            top.pending = None;
            if arg.starts_with("--") {
                top.parse_long(arg)?;
            } else {
                top.parse_short_cluster(arg)?;
            }
            continue;
        }
        if let Some(a) = top.pending.take() {
            top.add_value(a, arg.clone());
            continue;
        }
        // Positional or subcommand.
        if !top.trailing && top.def.subcommands.contains(&arg.as_str()) {
            let rest = &args[i..];
            let mut prefix = bin.to_string();
            if top.matches.positionals.is_empty() {
                prefix.push_str(" <input filename(s)>...");
            }
            if arg == "help" {
                return Err(run_help(bin, rest, &format!("{} image", prefix)));
            }
            prefix.push_str(" image");
            image = Some(parse_image(bin, prefix, rest)?);
            break;
        }
        if let Some(candidate) = did_you_mean(arg, top.def.subcommands.iter().copied()) {
            let body = format!(
                "The subcommand '{}' wasn't recognized\n\tDid you mean '{}'?\n\nIf you believe you received this message in error, try re-running with '{} -- {}'",
                arg, candidate, bin, arg
            );
            return Err(top.fail(body, top.error_usage(None)));
        }
        top.matches.positionals.push(arg.clone());
    }
    if image.is_some() {
        // The subcommand has been validated already; now the parent.
        top.validate()?;
    } else {
        top.validate()?;
    }
    Ok(ParsedArgs { bin_name: bin.to_string(), top: top.matches, image })
}

fn parse_image(bin: &str, prefix: String, args: &[String]) -> Result<Matches, Exit> {
    let mut p = Parser::new(bin, &IMAGE, prefix);
    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        i += 1;
        let starts_new_arg = !p.trailing && arg.starts_with('-') && arg.len() > 1;
        if !p.trailing && arg == "--" && p.pending.is_none() {
            p.trailing = true;
            continue;
        }
        if starts_new_arg {
            p.pending = None;
            if arg.starts_with("--") {
                p.parse_long(arg)?;
            } else {
                p.parse_short_cluster(arg)?;
            }
            continue;
        }
        if let Some(a) = p.pending.take() {
            p.add_value(a, arg.clone());
            continue;
        }
        return Err(p.unknown_argument(arg, None));
    }
    p.validate()?;
    Ok(p.matches)
}
