//! Command line parsing.
//!
//! The interface (help texts, usage lines and error messages) follows the
//! conventions of the classic clap 2 style: short/long flags, options taking a
//! value either as the next argument or attached (`-w5`, `-w=5`, `--yaw=1`),
//! clustered short flags (`-bx 1`), a `--` terminator, a `help` subcommand and
//! "did you mean" suggestions based on the Jaro-Winkler similarity.

use std::collections::HashMap;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Kind {
    Flag,
    Opt,
}

#[derive(Clone, Copy, Debug)]
struct ArgDef {
    /// Internal name; also used as the value placeholder for options.
    name: &'static str,
    short: Option<char>,
    long: Option<&'static str>,
    kind: Kind,
    required: bool,
}

impl ArgDef {
    /// Rendering used in usage strings and error messages.
    fn display(&self) -> String {
        let head = match (self.long, self.short) {
            (Some(l), _) => format!("--{}", l),
            (None, Some(s)) => format!("-{}", s),
            (None, None) => String::new(),
        };
        match self.kind {
            Kind::Flag => head,
            Kind::Opt => format!("{} <{}>", head, self.name),
        }
    }
}

const fn flag(name: &'static str, short: Option<char>, long: Option<&'static str>) -> ArgDef {
    ArgDef { name, short, long, kind: Kind::Flag, required: false }
}

const fn opt(name: &'static str, short: Option<char>, long: Option<&'static str>, required: bool) -> ArgDef {
    ArgDef { name, short, long, kind: Kind::Opt, required }
}

/// Definition of one (sub)command.
struct CmdDef {
    name: &'static str,
    args: &'static [ArgDef],
    /// Name of the (required, multiple) positional argument, if any.
    positional: Option<&'static str>,
    subcommands: &'static [&'static str],
    /// Short flag triggering the help output (`-h` is an option in `image`).
    help_short: Option<char>,
}

const TOP_ARGS: &[ArgDef] = &[
    flag("help", Some('h'), Some("help")),
    flag("b", Some('b'), None),
    flag("version", Some('V'), Some("version")),
    opt("x", Some('x'), Some("yaw"), false),
    opt("y", Some('y'), Some("pitch"), false),
    opt("z", Some('z'), Some("roll"), false),
];

const IMAGE_ARGS: &[ArgDef] = &[
    flag("help", None, Some("help")),
    flag("b", Some('b'), None),
    flag("version", Some('V'), Some("version")),
    opt("frame count", Some('j'), Some("webify"), false),
    opt("height", Some('h'), None, false),
    opt("width", Some('w'), None, true),
    opt("x", Some('x'), Some("yaw"), false),
    opt("y", Some('y'), Some("pitch"), false),
    opt("z", Some('z'), Some("roll"), false),
];

const TOP: CmdDef = CmdDef {
    name: "",
    args: TOP_ARGS,
    positional: Some("input filename(s)"),
    subcommands: &["help", "image"],
    help_short: Some('h'),
};

const IMAGE: CmdDef = CmdDef {
    name: "image",
    args: IMAGE_ARGS,
    positional: None,
    subcommands: &[],
    help_short: None,
};

const GOOD_START: &str = "\x1b[32m";
const GOOD_END: &str = "\x1b[0m";

/// Result of a parse that terminates the program (help, version or error).
#[derive(Debug, Clone)]
pub struct Exit {
    pub message: String,
    pub code: i32,
}

impl Exit {
    fn error(message: String) -> Exit {
        Exit { message, code: 1 }
    }

    fn output(message: String) -> Exit {
        Exit { message, code: 0 }
    }
}

/// Values collected for one command.
#[derive(Debug, Default, Clone)]
pub struct Matches {
    occurrences: HashMap<&'static str, u32>,
    values: HashMap<&'static str, Vec<String>>,
    /// Argument names in the order they were first seen.
    order: Vec<&'static str>,
    pub positionals: Vec<String>,
}

impl Matches {
    pub fn is_present(&self, name: &str) -> bool {
        self.occurrences.contains_key(name)
    }

    pub fn value_of(&self, name: &str) -> Option<&str> {
        self.values.get(name).and_then(|v| v.first()).map(|s| s.as_str())
    }

    fn note(&mut self, name: &'static str) {
        if !self.occurrences.contains_key(name) {
            self.order.push(name);
        }
        *self.occurrences.entry(name).or_insert(0) += 1;
    }
}

/// Fully parsed command line.
#[derive(Debug, Clone)]
pub struct ParsedArgs {
    pub bin_name: String,
    pub top: Matches,
    pub image: Option<Matches>,
}

// ---------------------------------------------------------------------------
// Help texts
// ---------------------------------------------------------------------------

pub fn top_help(bin: &str) -> String {
