//! sloth - a small command line 3D renderer.
//!
//! Renders Wavefront OBJ / STL models either as an animated view inside the
//! terminal, as a single static image, or as a set of frames for the web.

mod cli;
mod geometry;
mod inputs;
mod render;
mod term;

use geometry::{Rotation, Triangle};
use render::Frame;
use std::io::{self, Write};
use std::path::Path;
use std::time::Instant;

/// Parses a float option, mirroring `str::parse::<f32>` error reporting.
fn parse_float(value: Option<&str>) -> Result<f32, String> {
    match value {
        Some(v) => v.parse::<f32>().map_err(|e| format!("{:?}", e)),
        None => Ok(0.0),
    }
}

fn parse_usize(value: &str) -> Result<usize, String> {
    value.parse::<usize>().map_err(|e| format!("{:?}", e))
}

fn parse_i32(value: &str) -> Result<i32, String> {
    value.parse::<i32>().map_err(|e| format!("{:?}", e))
}

fn parse_rotation(m: &cli::Matches) -> Result<Rotation, String> {
    let x = parse_float(m.value_of("x"))?;
    let y = parse_float(m.value_of("y"))?;
    let z = parse_float(m.value_of("z"))?;
    Ok(Rotation { x, y, z })
}

/// Formats an I/O error the way the terminal back end reports it.
fn io_error(e: io::Error) -> String {
    format!("IoError({:?})", e)
}

fn write_error(e: io::Error) -> String {
    format!("IoError({:?})", io::Error::new(io::ErrorKind::Other, e))
}

/// Static image / web export.
fn run_image(tris: &[Triangle], colorless: bool, m: &cli::Matches) -> Result<(), String> {
    let width = parse_usize(m.value_of("width").unwrap_or("0"))?;
    let height = match m.value_of("height") {
        Some(h) => parse_usize(h)?,
        None => width,
    };
    let rotation = parse_rotation(m)?;

    if m.is_present("frame count") {
        let frames = parse_i32(m.value_of("frame count").unwrap_or("0"))? as usize;
        let step = std::f32::consts::PI * 2.0 / frames as f32;
        let mut angle = 0.0f32;
        let mut index = 0usize;
        print!("let frames = [\n");
        loop {
            let mut frame = Frame::new(width, height, true);
            let rot = Rotation { x: rotation.x, y: rotation.y + angle, z: rotation.z };
            frame.draw(tris, &rot);
            print!("`\n");
            if colorless {
                println!("{}", frame.to_plain_string());
            } else {
                print!("{}", frame.to_html_string());
            }
            print!("`");
            index += 1;
            angle += step;
            if index >= frames {
                break;
            }
            print!(",\n");
        }
        println!("];");
        return Ok(());
    }

    let mut frame = Frame::new(width, height, true);
    frame.draw(tris, &rotation);
    if colorless {
        println!("{}", frame.to_plain_string());
    } else {
        let stdout = io::stdout();
        let mut out = io::BufWriter::new(stdout.lock());
        frame.write_colored(&mut out).map_err(write_error)?;
        out.flush().map_err(write_error)?;
    }
    Ok(())
}

/// Interactive terminal view: the model spins around its vertical axis until
/// `q` (or Ctrl-C) is pressed.
fn run_terminal(tris: &[Triangle], colorless: bool, rotation: Rotation) -> Result<(), String> {
    let raw = term::RawMode::enable().map_err(io_error)?;
    let start = Instant::now();
    let stdout = io::stdout();
    let result = (|| -> io::Result<()> {
        let mut out = stdout.lock();
        write!(out, "\x1b[?25l")?;
        out.flush()?;
        loop {
            let (cols, rows) = term::size();
            let mut frame = Frame::new(cols, rows, false);
            let angle = start.elapsed().as_secs_f32();
            let rot = Rotation { x: rotation.x, y: rotation.y + angle, z: rotation.z };
            frame.draw(tris, &rot);
            write!(out, "\x1b[1;1H")?;
            if colorless {
                writeln!(out, "{}", frame.to_plain_string())?;
            } else {
                frame.write_colored(&mut out)?;
            }
            out.flush()?;
            let input = term::read_input(1);
            if input.iter().any(|&b| b == b'q' || b == 0x03) {
                break;
            }
        }
        write!(out, "\x1b[?25h")?;
        out.flush()?;
        Ok(())
    })();
    drop(raw);
    result.map_err(io_error)
}

fn run(parsed: cli::ParsedArgs) -> Result<(), String> {
    let mut tris = inputs::load_models(&parsed.top.positionals[0]);
    geometry::normalize(&mut tris);
    let colorless = parsed.top.is_present("b");
    let rotation = parse_rotation(&parsed.top)?;
    match &parsed.image {
        Some(image) => run_image(&tris, colorless, image),
        None => run_terminal(&tris, colorless, rotation),
    }
}

fn main() {
    let args: Vec<String> = std::env::args_os().map(|a| a.to_string_lossy().into_owned()).collect();
    let bin = args
        .first()
        .and_then(|a| Path::new(a).file_name().map(|f| f.to_string_lossy().into_owned()))
        .unwrap_or_else(|| "sloth".to_string());
    let parsed = match cli::parse(&bin, &args[1..]) {
        Ok(p) => p,
        Err(exit) => {
            if exit.code == 0 {
                print!("{}", exit.message);
                let _ = io::stdout().flush();
            } else {
                eprint!("{}", exit.message);
            }
            std::process::exit(exit.code);
        }
    };
    if let Err(e) = run(parsed) {
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
}
