import sys,re
# decode colored or plain output into a grid string with '|' for newline cells; color letters optional
def decode(data, w):
    tok=re.compile(r'\x1b\[([0-9;]*)m|(.)', re.S)
    cells=[]; fg=None
    if '\x1b[' in data:
        for m in tok.finditer(data):
