                if c.startswith('38;2;'): fg=tuple(map(int,c.split(';')[2:]))
            else: cells.append((fg,m.group(2)))
    else:
        cells=[(None,ch) for ch in data]
    out=[]
    for fg,ch in cells:
        if ch=='\n': out.append('|')
        elif ch==' ' and fg not in (None,(0,0,0)): out.append('_')
