mod data;
use std::collections::HashSet;
const W: usize = 40; const H: usize = 20;
type T = f32;
#[derive(Clone, Copy)] struct V { x: T, y: T, z: T }
fn sub(a: V, b: V) -> V { V { x: a.x - b.x, y: a.y - b.y, z: a.z - b.z } }
fn cross(a: V, b: V) -> V { V { x: a.y * b.z - a.z * b.y, y: a.z * b.x - a.x * b.z, z: a.x * b.y - a.y * b.x } }
fn dot(a: V, b: V) -> T { a.x * b.x + a.y * b.y + a.z * b.z }

fn edge(a: (T,T), b: (T,T), p: (T,T)) -> T { (b.0 - a.0) * (p.1 - a.1) - (b.1 - a.1) * (p.0 - a.0) }

// returns Some(true) if inside
fn inside(variant: usize, v: [V;3], p: (T,T)) -> bool {
    let a = (v[0].x, v[0].y); let b = (v[1].x, v[1].y); let c = (v[2].x, v[2].y);
    match variant {
        0 => { // edge functions / area
            let area = edge(a,b,c); if area == 0.0 { return false; }
            let w0 = edge(b,c,p)/area; let w1 = edge(c,a,p)/area; let w2 = edge(a,b,p)/area;
            w0 >= 0.0 && w1 >= 0.0 && w2 >= 0.0 }
        1 => { // tiny
            let s0 = (c.0 - a.0, b.0 - a.0, a.0 - p.0); let s1 = (c.1 - a.1, b.1 - a.1, a.1 - p.1);
            let ux = s0.1 * s1.2 - s0.2 * s1.1; let uy = s0.2 * s1.0 - s0.0 * s1.2; let uz = s0.0 * s1.1 - s0.1 * s1.0;
            if uz.abs() < 1e-2 { return false; }
            let bc = (1.0 - (ux + uy) / uz, uy / uz, ux / uz);
            !(bc.0 < 0.0 || bc.1 < 0.0 || bc.2 < 0.0) }
        2 => { // tiny with abs(uz) check and >=
            let s0 = (c.0 - a.0, b.0 - a.0, a.0 - p.0); let s1 = (c.1 - a.1, b.1 - a.1, a.1 - p.1);
            let ux = s0.1 * s1.2 - s0.2 * s1.1; let uy = s0.2 * s1.0 - s0.0 * s1.2; let uz = s0.0 * s1.1 - s0.1 * s1.0;
            if uz == 0.0 { return false; }
            let bc = (1.0 - (ux + uy) / uz, uy / uz, ux / uz);
            bc.0 >= 0.0 && bc.1 >= 0.0 && bc.2 >= 0.0 }
        3 => { // cramer 2d
            let v0 = (b.0 - a.0, b.1 - a.1); let v1 = (c.0 - a.0, c.1 - a.1); let v2 = (p.0 - a.0, p.1 - a.1);
            let d00 = v0.0*v0.0 + v0.1*v0.1; let d01 = v0.0*v1.0 + v0.1*v1.1; let d11 = v1.0*v1.0 + v1.1*v1.1;
            let d20 = v2.0*v0.0 + v2.1*v0.1; let d21 = v2.0*v1.0 + v2.1*v1.1;
            let denom = d00 * d11 - d01 * d01; if denom == 0.0 { return false; }
            let vv = (d11 * d20 - d01 * d21) / denom; let ww = (d00 * d21 - d01 * d20) / denom; let uu = 1.0 - vv - ww;
            uu >= 0.0 && vv >= 0.0 && ww >= 0.0 }
        4 => { // 3D cramer with z of vertices, point p with z = 0
            let pp = V { x: p.0, y: p.1, z: 0.0 };
            let v0 = sub(v[1], v[0]); let v1 = sub(v[2], v[0]); let v2 = sub(pp, v[0]);
            let d00 = dot(v0,v0); let d01 = dot(v0,v1); let d11 = dot(v1,v1); let d20 = dot(v2,v0); let d21 = dot(v2,v1);
            let denom = d00 * d11 - d01 * d01; if denom == 0.0 { return false; }
            let vv = (d11 * d20 - d01 * d21) / denom; let ww = (d00 * d21 - d01 * d20) / denom; let uu = 1.0 - vv - ww;
            uu >= 0.0 && vv >= 0.0 && ww >= 0.0 }
        5 => { // 3D: normal-based areas: n = cross(b-a, c-a); w0 = dot(cross(c-b, p-b), n)/dot(n,n) ... p with z=0
            let pp = V { x: p.0, y: p.1, z: 0.0 };
            let n = cross(sub(v[1], v[0]), sub(v[2], v[0])); let nn = dot(n, n); if nn == 0.0 { return false; }
            let w0 = dot(cross(sub(v[2], v[1]), sub(pp, v[1])), n) / nn;
            let w1 = dot(cross(sub(v[0], v[2]), sub(pp, v[2])), n) / nn;
            let w2 = dot(cross(sub(v[1], v[0]), sub(pp, v[0])), n) / nn;
            w0 >= 0.0 && w1 >= 0.0 && w2 >= 0.0 }
        6 => { // edge functions, strict > with zero allowed via >= only for... (top-left rule variant): inside if all > 0 or == 0
            let area = edge(a,b,c); if area == 0.0 { return false; }
            let e0 = edge(b,c,p); let e1 = edge(c,a,p); let e2 = edge(a,b,p);
            if area > 0.0 { e0 >= 0.0 && e1 >= 0.0 && e2 >= 0.0 } else { e0 <= 0.0 && e1 <= 0.0 && e2 <= 0.0 } }
        7 => { // tiny 3D: s0 uses x's, s1 uses y's but with the z? no — use (A.x-P.x) etc. same as tiny; variant: cross order swapped
            let s0 = (c.0 - a.0, b.0 - a.0, a.0 - p.0); let s1 = (c.1 - a.1, b.1 - a.1, a.1 - p.1);
            let ux = s1.1 * s0.2 - s1.2 * s0.1; let uy = s1.2 * s0.0 - s1.0 * s0.2; let uz = s1.0 * s0.1 - s1.1 * s0.0;
            if uz == 0.0 { return false; }
            let bc = (1.0 - (ux + uy) / uz, uy / uz, ux / uz);
            bc.0 >= 0.0 && bc.1 >= 0.0 && bc.2 >= 0.0 }
        8 => { // edge functions without division, sign by area
            let area = edge(a,b,c); if area == 0.0 { return false; }
            let e0 = edge(b,c,p); let e1 = edge(c,a,p); let e2 = edge(a,b,p);
            let s = area.signum();
            e0 * s >= 0.0 && e1 * s >= 0.0 && e2 * s >= 0.0 }
        9 => { // "tiny" but computing with (P - A) convention: s0 = (B.x-A.x, C.x-A.x, A.x-P.x)...
            let s0 = (b.0 - a.0, c.0 - a.0, a.0 - p.0); let s1 = (b.1 - a.1, c.1 - a.1, a.1 - p.1);
            let ux = s0.1 * s1.2 - s0.2 * s1.1; let uy = s0.2 * s1.0 - s0.0 * s1.2; let uz = s0.0 * s1.1 - s0.1 * s1.0;
            if uz == 0.0 { return false; }
            let bc = (1.0 - (ux + uy) / uz, ux / uz, uy / uz);
            bc.0 >= 0.0 && bc.1 >= 0.0 && bc.2 >= 0.0 }
        _ => unreachable!(),
    }
}

fn simulate(variant: usize, proj: usize, tri: &[(f64,f64,f64);3]) -> HashSet<(i32,i32)> {
    let s = (W as T / 4.0).min(H as T / 2.0); let cx = W as T / 4.0; let cy = H as T / 2.0;
    let mut v = [V{x:0.0,y:0.0,z:0.0};3];
    for i in 0..3 {
        let (x,y,z) = (tri[i].0 as f32, tri[i].1 as f32, tri[i].2 as f32);
        let (px, py) = match proj { 0 => (cx - x*s, cy - y*s), 1 => ((1.0 - x) * s + (cx - s), (1.0 - y) * s + (cy - s)), _ => (s*(1.0-x) + (cx-s), s*(1.0-y) + (cy-s)) };
        v[i] = V { x: px, y: py, z };
    }
    let xmin = v.iter().map(|p| p.x).fold(T::INFINITY, T::min); let xmax = v.iter().map(|p| p.x).fold(T::NEG_INFINITY, T::max);
    let ymin = v.iter().map(|p| p.y).fold(T::INFINITY, T::min); let ymax = v.iter().map(|p| p.y).fold(T::NEG_INFINITY, T::max);
    let r0 = (ymin.ceil() as i32).max(1); let r1 = (ymax.ceil() as i32).min(H as i32 - 1);
    let p0 = (xmin.ceil() as i32).max(1); let p1 = xmax.floor() as i32;
    let mut out = HashSet::new();
    for r in r0..r1 { for p in p0..=p1 { if inside(variant, v, (p as T, r as T)) { out.insert((r,p)); } } }
    out
}

fn main() {
    for proj in 0..3 { for variant in 0..10 {
        let mut exact = 0; let mut diff = 0;
        for (tri, drawn) in data::CASES {
            let got = simulate(variant, proj, tri);
            let obs: HashSet<(i32,i32)> = drawn.iter().cloned().collect();
            if got == obs { exact += 1; }
            diff += got.symmetric_difference(&obs).count();
        }
        println!("proj={} variant={} exact={}/{} pixdiff={}", proj, variant, exact, data::CASES.len(), diff);
    }}
}
