mod data;
use std::collections::HashSet;
const W: usize = 40; const H: usize = 20;
type T = f32;
#[derive(Clone, Copy, Debug)] struct V { x: T, y: T, z: T }
fn sub(a: V, b: V) -> V { V { x: a.x - b.x, y: a.y - b.y, z: a.z - b.z } }
fn cross(a: V, b: V) -> V { V { x: a.y * b.z - a.z * b.y, y: a.z * b.x - a.x * b.z, z: a.x * b.y - a.y * b.x } }
fn edge(a: (T,T), b: (T,T), p: (T,T)) -> T { (b.0 - a.0) * (p.1 - a.1) - (b.1 - a.1) * (p.0 - a.0) }

/// returns barycentric weights (w0,w1,w2) for vertex a,b,c
fn bary(variant: usize, a: (T,T), b: (T,T), c: (T,T), p: (T,T)) -> Option<[T;3]> {
    match variant {
        0 => { let area = edge(a,b,c); if area == 0.0 { return None; }
               Some([edge(b,c,p)/area, edge(c,a,p)/area, edge(a,b,p)/area]) }
        1 => { // tiny
            let s0 = (c.0 - a.0, b.0 - a.0, a.0 - p.0); let s1 = (c.1 - a.1, b.1 - a.1, a.1 - p.1);
            let ux = s0.1 * s1.2 - s0.2 * s1.1; let uy = s0.2 * s1.0 - s0.0 * s1.2; let uz = s0.0 * s1.1 - s0.1 * s1.0;
            if uz == 0.0 { return None; }
            Some([1.0 - (ux + uy) / uz, uy / uz, ux / uz]) }
        2 => { // cramer
            let v0 = (b.0 - a.0, b.1 - a.1); let v1 = (c.0 - a.0, c.1 - a.1); let v2 = (p.0 - a.0, p.1 - a.1);
            let d00 = v0.0*v0.0 + v0.1*v0.1; let d01 = v0.0*v1.0 + v0.1*v1.1; let d11 = v1.0*v1.0 + v1.1*v1.1;
            let d20 = v2.0*v0.0 + v2.1*v0.1; let d21 = v2.0*v1.0 + v2.1*v1.1;
            let denom = d00 * d11 - d01 * d01; if denom == 0.0 { return None; }
            let vv = (d11 * d20 - d01 * d21) / denom; let ww = (d00 * d21 - d01 * d20) / denom;
            Some([1.0 - vv - ww, vv, ww]) }
        3 => { // wiki det
            let det = (b.1 - c.1) * (a.0 - c.0) + (c.0 - b.0) * (a.1 - c.1); if det == 0.0 { return None; }
            let l1 = ((b.1 - c.1) * (p.0 - c.0) + (c.0 - b.0) * (p.1 - c.1)) / det;
            let l2 = ((c.1 - a.1) * (p.0 - c.0) + (a.0 - c.0) * (p.1 - c.1)) / det;
            Some([l1, l2, 1.0 - l1 - l2]) }
        4 => { // edge with 1/area
            let area = edge(a,b,c); if area == 0.0 { return None; } let inv = 1.0 / area;
            Some([edge(b,c,p)*inv, edge(c,a,p)*inv, edge(a,b,p)*inv]) }
        5 => { // areas abs /2
            let ta = |a: (T,T), b: (T,T), c: (T,T)| ((b.0 - a.0) * (c.1 - a.1) - (c.0 - a.0) * (b.1 - a.1)).abs() / 2.0;
            let at = ta(a,b,c); if at == 0.0 { return None; }
            Some([ta(p,b,c)/at, ta(a,p,c)/at, ta(a,b,p)/at]) }
        6 => { // tiny variant with w computed as 1 - u - v separately
            let s0 = (c.0 - a.0, b.0 - a.0, a.0 - p.0); let s1 = (c.1 - a.1, b.1 - a.1, a.1 - p.1);
            let ux = s0.1 * s1.2 - s0.2 * s1.1; let uy = s0.2 * s1.0 - s0.0 * s1.2; let uz = s0.0 * s1.1 - s0.1 * s1.0;
            if uz == 0.0 { return None; }
            let v = uy / uz; let w = ux / uz;
            Some([1.0 - v - w, v, w]) }
        7 => { // edge function normalized by sum of edges
            let e0 = edge(b,c,p); let e1 = edge(c,a,p); let e2 = edge(a,b,p); let s = e0 + e1 + e2; if s == 0.0 { return None; }
            Some([e0/s, e1/s, e2/s]) }
        _ => unreachable!(),
    }
}

fn interp(iv: usize, w: [T;3], n: [T;3]) -> T {
    match iv {
        0 => w[0]*n[0] + w[1]*n[1] + w[2]*n[2],
        1 => (w[0] + w[1] + w[2]) * n[0],
        2 => n[0] * (w[0] + w[1] + w[2]),
        3 => w[0]*n[0] + (w[1]*n[1] + w[2]*n[2]),
        4 => (w[2]*n[2] + w[1]*n[1]) + w[0]*n[0],
        5 => { let s = w[0] + w[1]; (s + w[2]) * n[0] },
        6 => { // interpolated normal vector then dot with (0,0,1) then... same as 0 but with normalize of the interpolated vector
            let nz = w[0]*n[0] + w[1]*n[1] + w[2]*n[2]; let nx = 0.0f32; let ny = 0.0f32;
            let len = (nx*nx + ny*ny + nz*nz).sqrt(); nz / len },
        7 => { // mean of vertex intensities weighted: n0*w0 + n1*w1 + n2*w2 using mul_add? emulate fma
            w[0].mul_add(n[0], w[1].mul_add(n[1], w[2]*n[2])) },
        _ => unreachable!(),
    }
}

fn nz_variant(nv: usize, v: [V;3]) -> T {
    // normal from model-space (scaled) vertices
    match nv {
        0 => 1.0,
        1 => { let n = cross(sub(v[1], v[0]), sub(v[2], v[0])); let len = (n.x*n.x + n.y*n.y + n.z*n.z).sqrt(); n.z / len }
        2 => { let n = cross(sub(v[1], v[0]), sub(v[2], v[0])); let len = (n.x*n.x + n.y*n.y + n.z*n.z).sqrt(); n.z * (1.0 / len) }
        3 => { let n = cross(sub(v[2], v[0]), sub(v[1], v[0])); let len = (n.x*n.x + n.y*n.y + n.z*n.z).sqrt(); -n.z / len }
        4 => { // normal computed in f64 then cast
            let a = (v[0].x as f64, v[0].y as f64, v[0].z as f64); let b = (v[1].x as f64, v[1].y as f64, v[1].z as f64); let c = (v[2].x as f64, v[2].y as f64, v[2].z as f64);
            let e1 = (b.0-a.0, b.1-a.1, b.2-a.2); let e2 = (c.0-a.0, c.1-a.1, c.2-a.2);
            let n = (e1.1*e2.2 - e1.2*e2.1, e1.2*e2.0 - e1.0*e2.2, e1.0*e2.1 - e1.1*e2.0);
            let len = (n.0*n.0 + n.1*n.1 + n.2*n.2).sqrt(); (n.2 / len) as f32 }
        5 => { let n = cross(sub(v[1], v[0]), sub(v[2], v[0])); let len2 = n.x*n.x + n.y*n.y + n.z*n.z; n.z / len2.sqrt() * 1.0 } 
        _ => unreachable!(),
    }
}

fn simulate(bv: usize, iv: usize, nv: usize, pv: usize, tri: &[(f64,f64,f64);3]) -> Option<(HashSet<(i32,i32)>, HashSet<(i32,i32)>)> {
    let s = (W as T / 4.0).min(H as T / 2.0); let cx = W as T / 4.0; let cy = H as T / 2.0;
    let mut v = [V{x:0.0,y:0.0,z:0.0};3]; let mut sc = [(0.0f32,0.0f32);3];
    for i in 0..3 {
        let (x,y,z) = (tri[i].0 as f32, tri[i].1 as f32, tri[i].2 as f32);
        v[i] = V { x, y, z };
        sc[i] = match pv { 0 => (cx - x*s, cy - y*s), 1 => ((1.0 - x) * s + (cx - s), (1.0 - y) * s + (cy - s)), 2 => (cx + (-x)*s, cy + (-y)*s), _ => (cx - s*x, cy - s*y) };
    }
    let nz = nz_variant(nv, v); let n = [nz, nz, nz];
