#[allow(dead_code)]
pub fn m1_detail(bv: usize) {
    for (name, tri, at, sp) in data::CASES {
        let s = 10.0f32; let cx = 10.0f32; let cy = 10.0f32;
        let mut sc = [(0.0f32,0.0f32);3];
        for i in 0..3 { let (x,y,z) = (tri[i].0 as f32, tri[i].1 as f32, tri[i].2 as f32); let (px,py,_) = transform_m1(x,y,z,s,cx,cy); sc[i] = (px,py); }
        let oat: HashSet<(i32,i32)> = at.iter().cloned().collect(); let osp: HashSet<(i32,i32)> = sp.iter().cloned().collect();
        let mut rows: Vec<i32> = oat.union(&osp).map(|p| p.0).collect(); rows.sort(); rows.dedup();
        let mut mism = 0; let mut lines = vec![];
        for r in rows {
            let mut line = String::new();
            for p in 0..21 {
                let obs = if oat.contains(&(r,p)) { '@' } else if osp.contains(&(r,p)) { '_' } else { continue_char() };
                if obs == '.' { line.push('.'); continue; }
                let w = bary(bv, sc[0], sc[1], sc[2], (p as f32, r as f32)).unwrap();
                let i = w[0] + w[1] + w[2];
                let sim = if i > 1.0 { '_' } else { '@' };
                let ulps = ((i as f64 - 1.0) / 2f64.powi(-24)).round() as i64;
                if sim != obs { mism += 1; line.push_str(&format!("[{}{}{:+}]", obs, sim, ulps)); } else { line.push_str(&format!("{}{:+} ", obs, ulps)); }
            }
            lines.push(format!("  r={:2} {}", r, line));
        }
        println!("{} screen={:?} mismatches={}", name, sc, mism);
        if mism > 0 { for l in lines { println!("{}", l); } }
    }
}
