//! Software rasterizer producing character frames.
//!
//! The frame is a grid of `width` character columns by `height` rows.  Every
//! logical pixel is two characters wide (to compensate for the usual 2:1
//! aspect ratio of terminal cells), so the scene is projected onto a
//! `width / 2` by `height` pixel grid.  Projection is orthographic: the scene
//! (normalised to the unit cube) is scaled so that it fits the smaller
//! dimension of the pixel grid and centred.  The viewer looks at the model
//! from the positive z side, which is realised by turning the scene half a
//! revolution around the vertical axis in front of the camera.
//!
//! Shading is flat: the geometric normal of a face is compared with a light
//! shining straight at the model and the resulting intensity is mapped onto
//! an ASCII brightness ramp.  Faces turned away from the viewer are culled.
//! A per-pixel depth buffer resolves visibility.
//!
//! When the frame is created for "image" output each row additionally carries
//! a line-break marker cell; the marker is placed in the second character of
//! the first (never drawn) pixel of every row touched by a face.
//!
//! All arithmetic is carried out in single precision on purpose: the exact
//! rounding behaviour is part of the observable output (which pixels along an
//! edge are covered, how coplanar faces resolve, ...).

use crate::geometry::{row_dot, Color, Mat3, Rotation, Triangle, Vec3};
use std::io::{self, Write};

/// Brightness ramp from bright to dark, indexed by `floor((1 - i) * 10)`.
const RAMP: [char; 10] = ['@', '%', '#', '*', '+', '=', '-', ':', '.', '.'];

/// Background colour of every cell.
pub const BACKGROUND: Color = Color::new(25, 25, 25);

/// A single character cell.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Cell {
    pub ch: char,
    pub fg: Color,
}

impl Cell {
    const BLANK: Cell = Cell { ch: ' ', fg: Color::new(0, 0, 0) };
}

pub struct Frame {
    pub width: usize,
    pub height: usize,
    image_mode: bool,
    cells: Vec<Cell>,
    depth: Vec<f32>,
}

/// Twice the signed area of the triangle `(a, b, p)`.
fn edge(a: (f32, f32), b: (f32, f32), p: (f32, f32)) -> f32 {
    (b.0 - a.0) * (p.1 - a.1) - (b.1 - a.1) * (p.0 - a.0)
}

/// Maps a light intensity onto the brightness ramp.  Intensities above one
/// (possible through interpolation round-off) fall off the ramp and yield a
/// blank character.
fn shade(intensity: f32) -> char {
    let index = ((1.0 - intensity) * 10.0).floor();
    if index < 0.0 || index >= RAMP.len() as f32 {
        ' '
    } else {
        RAMP[index as usize]
    }
}

impl Frame {
    /// Creates an empty frame.  In image mode every row has room for an extra
    /// line-break cell.
    pub fn new(width: usize, height: usize, image_mode: bool) -> Frame {
        let len = if image_mode { (width + 1) * height } else { width * height };
        Frame {
            width,
            height,
            image_mode,
            cells: vec![Cell::BLANK; len],
            depth: vec![f32::INFINITY; len],
        }
    }

    /// Rasterizes all triangles with the given rotation applied.
    pub fn draw(&mut self, tris: &[Triangle], rotation: &Rotation) {
        let w = self.width;
        let h = self.height as i64;
        let scale = (w as f32 / 4.0).min(self.height as f32 / 2.0);
        let cx = w as f32 / 4.0;
        let cy = self.height as f32 / 2.0;

        // Model rotation followed by the half turn that makes the model face
        // the viewer, then scaling to pixels (x mirrored by the half turn, y
        // flipped because rows grow downwards).
        let view = Mat3::rotation_y(std::f32::consts::PI).mul(&rotation.matrix());
        let row_x = view.scaled_row(0, scale);
        let row_y = view.scaled_row(1, -scale);
        let row_z = view.scaled_row(2, scale);

        for tri in tris {
            let mut pts = [Vec3::new(0.0, 0.0, 0.0); 3];
            for (k, v) in tri.v.iter().enumerate() {
                pts[k] = Vec3::new(row_dot(row_x, *v) + cx, row_dot(row_y, *v) + cy, row_dot(row_z, *v));
            }
            let [a, b, c] = pts;
            // Geometric normal in view space; the half turn above flips the
            // z axis, so a face pointing at the viewer has a negative z here.
            let normal = b.sub(a).cross(c.sub(a)).normalized();
            let intensity = -normal.z;

            let sa = (a.x, a.y);
            let sb = (b.x, b.y);
            let sc = (c.x, c.y);
            let xmin = a.x.min(b.x).min(c.x);
            let xmax = a.x.max(b.x).max(c.x);
            let ymin = a.y.min(b.y).min(c.y);
            let ymax = a.y.max(b.y).max(c.y);
            if !(xmin.is_finite() && xmax.is_finite() && ymin.is_finite() && ymax.is_finite()) {
                continue;
            }

            let r0 = (ymin.ceil() as i64).max(1);
            let r1 = (ymax.ceil() as i64).min(h - 1);
            let p0 = (xmin.ceil() as i64).max(1);
            let p1 = xmax.floor() as i64;
            let area = edge(sa, sb, sc);
            let visible = intensity > 0.0 && area != 0.0;

            for r in r0..r1 {
                if self.image_mode {
                    let marker = r as usize * w + 1;
                    if marker < self.cells.len() {
                        self.cells[marker] = Cell { ch: '\n', ..Cell::BLANK };
                    }
                }
                if !visible {
                    continue;
                }
                for p in p0..=p1 {
                    let point = (p as f32, r as f32);
                    let w0 = edge(sb, sc, point) / area;
                    let w1 = edge(sc, sa, point) / area;
                    let w2 = edge(sa, sb, point) / area;
                    if !(w0 >= 0.0 && w1 >= 0.0 && w2 >= 0.0) {
                        continue;
                    }
                    let idx = r as usize * w + 2 * p as usize;
                    if idx + 1 >= self.cells.len() {
                        continue;
                    }
                    // Depth grows away from the viewer in view space.
                    let z = (w0 * a.z + w1 * b.z) + w2 * c.z;
                    if z < self.depth[idx] {
                        self.depth[idx] = z;
                        let i = (w0 * intensity + w1 * intensity) + w2 * intensity;
                        let cell = Cell { ch: shade(i), fg: tri.color };
                        self.cells[idx] = cell;
                        self.cells[idx + 1] = cell;
                    }
                }
            }
        }
    }

    /// The frame as plain text (used by the colourless modes).
    pub fn to_plain_string(&self) -> String {
        self.cells.iter().map(|c| c.ch).collect()
    }

    /// Writes the frame as coloured terminal cells.
    pub fn write_colored<W: Write>(&self, out: &mut W) -> io::Result<()> {
        for cell in &self.cells {
            write!(
                out,
                "\x1b[48;2;{};{};{}m\x1b[38;2;{};{};{}m{}\x1b[49m\x1b[39m",
                BACKGROUND.r, BACKGROUND.g, BACKGROUND.b, cell.fg.r, cell.fg.g, cell.fg.b, cell.ch
            )?;
        }
        Ok(())
    }

    /// The frame as HTML spans (used by the web export).
    pub fn to_html_string(&self) -> String {
        let mut s = String::with_capacity(self.cells.len() * 40);
        for cell in &self.cells {
            s.push_str(&format!("<span style=\"color:rgb({},{},{})\">{}", cell.fg.r, cell.fg.g, cell.fg.b, cell.ch));
        }
        s
    }
}
