new='''/// Parses up to `n` floats, stopping silently at the first missing value but
/// failing on a value that is not a number.  Returns the parsed values.
fn parse_up_to(words: &mut std::str::SplitWhitespace, n: usize, err: LoadError) -> Result<Vec<f32>, LoadError> {
    let mut out = Vec::with_capacity(n);
    for _ in 0..n {
        match words.next() {
            Some(w) => out.push(w.parse::<f32>().map_err(|_| err)?),
            None => break,
        }
    }
    Ok(out)
}

/// Resolves a one-based (possibly negative, i.e. relative) index.
fn resolve_index(idx: isize, count: usize, err: LoadError) -> Result<usize, LoadError> {
    let resolved = if idx > 0 {
        idx - 1
    } else if idx < 0 {
        count as isize + idx
    } else {
        return Err(err);
    };
    if resolved < 0 || resolved as usize >= count {
        return Err(err);
    }
    Ok(resolved as usize)
}

/// Resolves a single face vertex reference ("i", "i/t", "i//n", "i/t/n") and
/// validates the referenced texture coordinate / normal indices.
fn face_index(word: &str, counts: (usize, usize, usize)) -> Result<usize, LoadError> {
    let mut parts = word.split('/');
    let idx_str = parts.next().ok_or(LoadError::FaceParseError)?;
    let idx: isize = idx_str.parse().map_err(|_| LoadError::FaceParseError)?;
    let vertex = resolve_index(idx, counts.0, LoadError::FaceVertexOutOfBounds)?;
    if let Some(t) = parts.next() {
        if !t.is_empty() {
            let ti: isize = t.parse().map_err(|_| LoadError::FaceParseError)?;
            if ti != 0 {
                resolve_index(ti, counts.1, LoadError::FaceTexCoordOutOfBounds)?;
            }
        }
    }
