new='''/// Parses up to `n` floats, stopping silently at the first missing value but
/// failing on a value that is not a number.  Returns the parsed values.
fn parse_up_to(words: &mut std::str::SplitWhitespace, n: usize, err: LoadError) -> Result<Vec<f32>, LoadError> {
    let mut out = Vec::with_capacity(n);
    for _ in 0..n {
        match words.next() {
            Some(w) => out.push(w.parse::<f32>().map_err(|_| err)?),
            None => break,
        }
    }
    Ok(out)
}

/// Resolves a one-based (possibly negative, i.e. relative) index.
fn resolve_index(idx: isize, count: usize, err: LoadError) -> Result<usize, LoadError> {
    let resolved = if idx > 0 {
        idx - 1
    } else if idx < 0 {
        count as isize + idx
    } else {
        return Err(err);
    };
    if resolved < 0 || resolved as usize >= count {
        return Err(err);
    }
    Ok(resolved as usize)
}

